DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.admin_clear_demo()'::regprocedure) INTO f; f:=replace(f,'FOREACH t IN ARRAY','DELETE FROM season_entries WHERE is_demo; FOREACH t IN ARRAY');EXECUTE f;
SELECT pg_get_functiondef('public.guard_account_content()'::regprocedure) INTO f; f:=replace(f,'RETURN NEW; END','IF TG_OP<>''DELETE'' AND TG_TABLE_NAME<>''profiles'' AND j ? ''user_id'' AND EXISTS(SELECT 1 FROM profiles WHERE id=(j->>''user_id'')::uuid AND is_demo) THEN NEW:=jsonb_populate_record(NEW,jsonb_build_object(''is_demo'',true)); END IF; RETURN NEW; END');EXECUTE f;END $$;